def transform(g):
    H,W=len(g),len(g[0])
    step = -1 if any(x==2 for x in g[0]) else 1
    grid=[r[:] for r in g]
    def objects():
        seen=[[False]*W for _ in range(H)]; objs=[]
        for r in range(H):
            for c in range(W):
                if grid[r][c] not in (0,2) and not seen[r][c]:
                    col=grid[r][c]; stack=[(r,c)]; cells=[]; seen[r][c]=True
                    while stack:
                        y,x=stack.pop(); cells.append((y,x))
                        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and grid[ny][nx]==col:
                                seen[ny][nx]=True; stack.append((ny,nx))
                    objs.append(cells)
        return objs
    def can_move(cells):
        for y,x in cells:
            ny=y+step
            if not (0<=ny<H) or grid[ny][x]==2: return False
            if grid[ny][x]!=0 and (ny,x) not in cells: return False
        return True
    while True:
        mov=[cells for cells in objects() if can_move(cells)]
        if not mov: break
        if step==-1:
            cells=min(mov, key=lambda cs: min(y for y,x in cs))
        else:
            cells=max(mov, key=lambda cs: max(y for y,x in cs))
        vals=[(grid[y][x],y,x) for y,x in cells]
        for v,y,x in vals: grid[y][x]=0
        for v,y,x in vals: grid[y+step][x]=v
    return grid

