def transform(g):
    H,W=len(g),len(g[0])
    step = -1 if any(x==2 for x in g[0]) else 1
    # pieces from input
    seen=[[False]*W for _ in range(H)]; pieces=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] not in (0,2) and not seen[r][c]:
                col=g[r][c]; stack=[(r,c)]; cells=[]; seen[r][c]=True
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True; stack.append((ny,nx))
                pieces.append({'col':col,'cells':set(cells)})
    pos=[p['cells'] for p in pieces]
    def can_move(cells):
        for y,x in cells:
            ny=y+step
            if not (0<=ny<H) or g[ny][x]==2: return False
            if g[ny][x]!=0 and (ny,x) not in cells:
                # occupied by another piece?
                if any((ny,x) in pc and pc is not cells for pc in pos): return False
        return True
    def occupied():
        occ={}
        for i,pc in enumerate(pos):
            for y,x in pc: occ[(y,x)]=i
        return occ
    while True:
        occ=occupied()
        mov=[]
        for i,pc in enumerate(pos):
            ok=True
            for y,x in pc:
                ny=y+step
                if not (0<=ny<H) or g[ny][x]==2: ok=False;break
                if (ny,x) in occ and occ[(ny,x)]!=i: ok=False;break
            if ok: mov.append((i,pc))
        if not mov: break
        if step==-1: i,pc=min(mov,key=lambda t:min(y for y,x in t[1]))
        else: i,pc=max(mov,key=lambda t:max(y for y,x in t[1]))
        pos[i]={(y+step,x) for y,x in pc}
    grid=[[0]*W for _ in range(H)]
    for r in range(W) if False else []: pass
    for r in range(H):
        for c in range(W):
            if g[r][c]==2: grid[r][c]=2
    for i,p in enumerate(pieces):
        for y,x in pos[i]: grid[y][x]=p['col']
    return grid

